import React, { useEffect, useState } from 'react';
import axios from 'axios';

export default function HostDashboard() {
  const [experiences, setExperiences] = useState([]);
  const [newExperience, setNewExperience] = useState({
    title: '',
    description: '',
    price: 0,
    capacity: 1,
    media: [],
    location: { coordinates: [0, 0] } // Default coordinates
  });

  useEffect(() => {
    const fetchHostExperiences = async () => {
      const token = localStorage.getItem('token');
      if (!token) {
        // Redirect to login or show message
        return;
      }
      try {
        const response = await axios.get(`${process.env.REACT_APP_API_URL || 'http://localhost:5000'}/api/experiences/host`,
          { headers: { Authorization: `Bearer ${token}` } }
        );
        setExperiences(response.data);
      } catch (error) {
        console.error('Error fetching host experiences:', error);
      }
    };
    fetchHostExperiences();
  }, []);

  const handleInputChange = (e) => {
    const { name, value } = e.target;
    setNewExperience(prev => ({
      ...prev,
      [name]: value
    }));
  };

  const handleCreateExperience = async (e) => {
    e.preventDefault();
    const token = localStorage.getItem('token');
    if (!token) return;

    try {
      const response = await axios.post(`${process.env.REACT_APP_API_URL || 'http://localhost:5000'}/api/experiences`,
        { ...newExperience, price: newExperience.price * 100 }, // Convert price to cents
        { headers: { Authorization: `Bearer ${token}` } }
      );
      setExperiences(prev => [...prev, response.data]);
      setNewExperience({ title: '', description: '', price: 0, capacity: 1, media: [], location: { coordinates: [0, 0] } });
      alert('Experience created successfully!');
    } catch (error) {
      console.error('Error creating experience:', error);
      alert('Failed to create experience.');
    }
  };

  return (
    <div>
      <h1>لوحة تحكم المضيف</h1>

      <h2>إنشاء تجربة جديدة</h2>
      <form onSubmit={handleCreateExperience}>
        <input type="text" name="title" placeholder="عنوان التجربة" value={newExperience.title} onChange={handleInputChange} required /><br/>
        <textarea name="description" placeholder="وصف التجربة" value={newExperience.description} onChange={handleInputChange} required></textarea><br/>
        <input type="number" name="price" placeholder="السعر (بالدولار)" value={newExperience.price} onChange={handleInputChange} required /><br/>
        <input type="number" name="capacity" placeholder="القدرة الاستيعابية" value={newExperience.capacity} onChange={handleInputChange} required /><br/>
        <input type="text" name="media" placeholder="روابط الصور (مفصولة بفاصلة)" value={newExperience.media.join(',')} onChange={e => setNewExperience(prev => ({ ...prev, media: e.target.value.split(',') }))} /><br/>
        {/* Add inputs for location coordinates if needed */}
        <button type="submit">إنشاء تجربة</button>
      </form>

      <h2>تجاربي الحالية</h2>
      {experiences.length === 0 ? (
        <p>لا توجد تجارب حالية.</p>
      ) : (
        <ul>
          {experiences.map(exp => (
            <li key={exp._id}>
              <h3>{exp.title}</h3>
              <p>{exp.description}</p>
              <p>السعر: ${(exp.price / 100).toFixed(2)}</p>
              {/* Add more details or edit/delete options */}
            </li>
          ))}
        </ul>
      )}
    </div>
  );
}
